          "citation": "Chapter 2 p. 180"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "dom7",
      "function_role": "avoid-note-4th-over-standalone-dominant",
      "narrative": "Benson states that when playing Dorian ideas over a standalone G7, 'we must be careful with the avoid note C, because it can make your melody sound weird or even incorrect... we definitely can use D dorian ideas over G7, but without forgetting to emphasize the B note instead the C note' (Chapter 2, p. 144).",
      "source_principle_ids": [
        "avoid-note-c-over-g7",
        "ii-v-superimposition"
      ],
      "source_work_id": "method-vol-4-approach-tones",
