      "cross_ref": [
        "sus4/exception-allowing-4th-as-target-tone"
      ],
      "granularity_level": "d",
      "granularity_name": "color-tone-policy"
    },
    {
      "chord_quality": "dom7",
      "function_role": "dorian-line-modification-to-remove-avoid-note",
      "narrative": "Benson provides a concrete editing rule: 'it is very important to remember that all the lines ending on the C note have to be modified when played over G7 because the C note is an avoid note for that chord' (Chapter 2, p. 146).",
      "source_principle_ids": [
        "avoid-note-c-over-g7"
      ],
      "source_work_id": "method-vol-4-approach-tones",
