    },
    {
      "chord_quality": "dom7",
      "function_role": "harmonic-minor-over-v7-cadential-use",
      "narrative": "Benson frames the harmonic minor scale as reserved specifically for dominant-function contexts: 'we will use its melodies over harmonic situations where we have tension & resolution' (Chapter 3, p. 235). He lists six valid cadential contexts including bare G7 | Cm7, Fm7 G7 | Cm7, and Dm7b5 G7 | Cm7.",
      "source_principle_ids": [
        "harmonic-minor-scale",
        "harmonic-minor-superimposition"
      ],
      "source_work_id": "method-vol-4-approach-tones",
      "references": [
