      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "dom7",
      "function_role": "tonic-root-omission-during-dominant",
      "narrative": "Benson warns against landing on the tonic root when superimposing the harmonic minor chord family over G7: 'be careful when using the root of the Cm(maj7), because it can sound weird, making the whole line sound incorrect. So the best thing to do is to forget the root for now' (Chapter 3, p. 308).",
      "source_principle_ids": [
        "tonic-root-omission-over-dominant",
        "passing-chord-tonic-note-rule"
      ],
      "source_work_id": "method-vol-4-approach-tones",
