      "granularity_name": "omission-priority"
    },
    {
      "chord_quality": "dom7",
      "function_role": "diminished-as-rootless-dominant-superimposition",
      "narrative": "Benson instructs that the VII diminished of C harmonic minor (B dim) and its three enharmonic equivalents (D dim, F dim, Ab dim) are all valid superimpositions over G7, because 'all of them are what we call fake diminished chords, because they are G7(b9) [V7] without the root note' (Chapter 3, p. 246).",
      "source_principle_ids": [
        "diminished-chord-rootless-v7",
        "diminished-symmetry-interchangeability",
        "harmonic-minor-superimposition"
      ],
