      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dom7",
      "function_role": "augmented-chord-as-embedded-melodic-cell",
      "narrative": "Benson explicitly prohibits consecutive use of augmented shapes over a dominant: 'Remember that these augmented chords are not to be played consecutively, they are just small melodic cells to help us build melodies using the harmonic minor scale' (Chapter 3, p. 284).",
      "source_principle_ids": [
        "augmented-as-melodic-cell-not-harmonic",
        "augmented-symmetry-interchangeability"
