    },
    {
      "chord_quality": "dom7",
      "function_role": "degree-substitution-to-avoid-tonic-note",
      "narrative": "Benson supplies a degree-by-degree substitution table: 'Second degree = Dm7b5: can be replaced by D dim; Fourth degree = Fm7: can be replaced by F dim or Fm7b5; Fifth degree = G7: can be replaced by G+7; Sixth degree = Abmaj7: can be replaced by Abm(maj7) or Ab dim(maj7)' (Chapter 3, p. 335).",
      "source_principle_ids": [
        "chord-family-degree-substitution-options",
        "tonic-root-omission-over-dominant"
