    },
    {
      "chord_quality": "dom7b9",
      "function_role": "diminished-rootless-v7b9-four-spellings",
      "narrative": "Benson establishes that 'B dim will provide us three more equal chords: D dim, F dim and Ab dim. However, all of them are what we call fake diminished chords, because they are G7(b9) [V7] without the root note' (Chapter 3, p. 246). The accompanying table maps each note to its G7(b9) function.",
      "source_principle_ids": [
